  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const r = await fetch(url, {
      signal: ctrl.signal,
      headers: {
        // Sensedia API Gateway (ANBIMA): usa header "access_token", nÃ£o "Authorization: Bearer"
        "access_token": access_token,
        "client_id": clientId,
        "Accept": "application/json"
      }
    });
    clearTimeout(t);
    if (!r.ok) {
      const txt = await r.text().catch(() => "");
      return { ok: false, status: r.status, motivo: txt.substring(0, 200) };
    }
    const data = await r.json();
    const itens = Array.isArray(data) ? data : data.data || data.items || data.resultado || [];
    return { ok: true, itens };
  } catch (e) {
    clearTimeout(t);
    return { ok: false, motivo: e.message };
  }
