    const usage = d?.data?.total_usage ?? 0;
    const saldo = Math.round((total - usage) * 100) / 100;
    let nivel = "normal";
    if (saldo < PROVIDER_LIMIARES.openrouter.critico) nivel = "critico";
    else if (saldo < PROVIDER_LIMIARES.openrouter.vermelho) nivel = "vermelho";
